/**
 * Parliament member directory, verified 2026-11-20.
 * Official membership, terms and portraits: https://sansad.in/ls/members and https://sansad.in/rs/members
 * Election declarations: https://www.myneta.info/LokSabha2024/ and https://www.myneta.info/rajsab09aff/
 * Membership and declarations are separate records. A missing filed value stays absent.
 */

export type HouseType = 'lok_sabha' | 'rajya_sabha';

export const MP_PROFILES_SNAPSHOT = {
  asOf: '2026-11-20',
  lokSabhaSeatCount: 543,
  rajyaSabhaSeatCount: 245,
} as const;

export interface MPProfile {
  id: string;
  name: string;
  party: string;
  stateCode: string;
  house: HouseType;
  constituency?: string;
  constituencyNo?: number;
  district?: string;
  gender: 'M' | 'F';
  age?: number;
  dob?: string;
  dobEstimated?: boolean;
  education?: string;
  profession?: string;
  terms: number;
  electedYear?: number;
  termStart?: string;
  termEnd?: string;
  affidavitUrl?: string;
  affidavitYear?: number;
  criminalCases?: number;
  totalAssets?: number;
  totalLiabilities?: number;
  maritalStatus?: 'Single' | 'Married' | 'Widowed' | 'Divorced';
  photoUrl?: string;
  sourceUrl?: string;
  isMinister?: boolean;
  ministerialPortfolio?: string;
  questionsAsked?: number;
  debatesParticipated?: number;
  citation?: string;
  verifiedAt?: string;
}

